arguments.command:
curl -sS -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "types=public_channel,private_channel&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for k in ('channels','groups'):
    for c in d.get(k,[]):
        if 'incident' in c['name'].lower(): print(k, c['id'], c['name'], 'archived' if c.get('is_archived') else '')
"

